<template><DetailsPanel :open="layout.details.chaos" :title="t('common.details')" @close="stores.uiLayout.toggleDetails('chaos')"><div class="scr-tech-grid"><span>{{ t('chaos.operation', { id: lifecycle.operationId || '—' }) }}</span><span>{{ t('chaos.generation', { value: lifecycle.operationGeneration || 0 }) }}</span><span>{{ t('chaos.phase', { value: core.lifecyclePhase || core.operationState }) }}</span><span>{{ t('chaos.target', { model: target.modelKey || '—', config: target.configKey || '—' }) }}</span><span v-if="transaction?.readBackStatus">readBackStatus: {{ transaction.readBackStatus }}</span><span v-if="candidateIds.length">candidateIdChain: {{ candidateIds.join(' → ') }}</span></div><button type="button" @click="stores.command.send('copyDiagnostics')">{{ t('status.copyDiagnostics') }}</button></DetailsPanel></template>
<script setup>
import { computed } from "vue"; import { useStores } from "../../stores"; import DetailsPanel from "../common/DetailsPanel.vue"
const stores = useStores(); const core = stores.core.state; const layout = stores.uiLayout.state; const { t } = stores.i18n
const lifecycle = computed(() => core.lifecycle || {}); const transaction = computed(() => core.transaction || null); const target = computed(() => transaction.value?.operationContext?.logicalTarget || {}); const candidateIds = computed(() => transaction.value?.candidateIdChain || [])
</script>
